-- PT112-S4-Q23. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT112-S4-Q23$batch10$ AND q.stimulus=$batch10$When investigators discovered that the director of a local charity had repeatedly overstated the number of people his charity had helped, the director accepted responsibility for the deception. However, the investigators claimed that journalists were as much to blame as the director was for inflating the charity’s reputation, since they had naïvely accepted what the director told them, and simply reported as fact the numbers he gave them.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if valid, most helps to justify the investigators' claim?$batch10$ AND q.correct_choice=$batch10$C$batch10$) THEN RAISE EXCEPTION 'Question changed: PT112-S4-Q23'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT112-S4-Q23$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S4-Q23'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT112-S4-Q23$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Journalists are as much to blame as the director for inflating the charity's reputation.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The journalists naively accepted the director's numbers and reported them as fact.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The journalists didn't lie. They passed along false numbers without checking. The principle has to make reporting an unverified story as fact just as blameworthy as the original deception.$batch10$), (3, $batch10$Goal$batch10$, $batch10$Anyone who reports an unverified story as fact is as responsible for its effects as anyone else.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT112-S4-Q23$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This covers people who work for a charity. The journalists don't, so it can't spread the blame to them.$batch10$), ($batch10$B$batch10$, $batch10$This covers people who knowingly help a liar hide the truth. The journalists were naive, not knowing accomplices.$batch10$), ($batch10$C$batch10$, $batch10$The journalists reported the numbers as fact without trying to verify them, and the story turned out to be false. This principle says they are no less responsible than anyone else, including the director. That is the investigators' claim.$batch10$), ($batch10$D$batch10$, $batch10$This ranks liars by motive. The journalists didn't lie, and the claim is about how blame is shared, not about motives.$batch10$), ($batch10$E$batch10$, $batch10$This would make the director less blameworthy for accepting responsibility. It says nothing about the journalists being equally to blame.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT112-S4-Q23$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
